import {
  serialize
} from "./chunk-TCXDBRRT.mjs";

// src/exporters/musicxml-compressed.ts
import { zipSync, strToU8 } from "fflate";
function serializeCompressed(score, options = {}) {
  const xmlString = serialize(score, options);
  const rootFileName = "score.xml";
  const containerXml = `<?xml version="1.0" encoding="UTF-8"?>
<container>
  <rootfiles>
    <rootfile full-path="${rootFileName}"/>
  </rootfiles>
</container>`;
  const files = {
    "META-INF/container.xml": strToU8(containerXml),
    [rootFileName]: strToU8(xmlString)
  };
  return zipSync(files, { level: 6 });
}

export {
  serializeCompressed
};
